 71	function parseStorage(storage: Storage): { data?: ManualParcelStorage; error?: string } {
 72	  try {
 73	    const raw = storage.getItem(MANUAL_PARCEL_STORAGE_KEY)
 74	    if (!raw) return { data: emptyStorage() }
 75	    const parsed = JSON.parse(raw) as Partial<ManualParcelStorage>
 76	    if (parsed.version !== 1 || !parsed.villages || typeof parsed.villages !== 'object' || Array.isArray(parsed.villages)) {
 77	      return { error: '本机人工地块数据版本不兼容，已停止写入以保护原记录。' }
 78	    }
 79	    return { data: parsed as ManualParcelStorage }
 80	  } catch {
 81	    return { error: '无法读取本机人工地块数据，已停止写入以保护原记录。' }
 82	  }
 83	}
 84	
 85	export function readManualParcels(villageCode: string, storage?: Storage): ManualParcelReadResult {
 86	  const resolved = browserStorage(storage)
 87	  if (!resolved) return { features: [], error: '当前浏览器不允许访问本机存储，人工地块无法读取或保存。' }
 88	  const parsed = parseStorage(resolved)
 89	  if (!parsed.data) return { features: [], error: parsed.error }
 90	  const records = parsed.data.villages[villageCode]
 91	  if (!Array.isArray(records)) return { features: [] }
 92	  const features = records.filter((feature) => isManualFeature(feature, villageCode))
 93	  return {
 94	    features,
 95	    error: features.length === records.length ? undefined : '部分本机人工地块记录无效，已跳过显示。',
 96	  }
 97	}
 98	
 99	export function writeManualParcels(
100	  villageCode: string,
101	  features: ManualParcelFeature[],
102	  storage?: Storage,
103	): { ok: true } | { ok: false; error: string } {
104	  const resolved = browserStorage(storage)
105	  if (!resolved) return { ok: false, error: '当前浏览器不允许访问本机存储，无法保存人工地块。' }
106	  const parsed = parseStorage(resolved)
107	  if (!parsed.data) return { ok: false, error: parsed.error ?? '无法读取本机人工地块。' }
108	  try {
109	    if (features.length) parsed.data.villages[villageCode] = features
110	    else delete parsed.data.villages[villageCode]
111	    resolved.setItem(MANUAL_PARCEL_STORAGE_KEY, JSON.stringify(parsed.data))
112	    return { ok: true }
113	  } catch {
114	    return { ok: false, error: '保存失败，请检查浏览器是否允许本地存储或存储空间是否充足。' }
115	  }
116	}
