118	function createId(): string {
119	  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return `manual-${crypto.randomUUID()}`
120	  return `manual-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
121	}
